package art

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/mellifera/mellifera/internal/store"
)

// The tombstone serve law's art side (tombstone-lifecycle 3.2): the settle
// walk's GC union read stays an explicit ALL-rows read — a tombstoned item's
// poster reference keeps its fetch row and blob dir alive while dead, so a
// self-heal (2.2) or adoption (2.3) finds the artwork intact.

// TestSettleUnionKeepsTombstonedRows pins the union posture against both
// failure directions: GC must RUN (an unreferenced row is reclaimed) and the
// tombstoned document's reference must SPARE its row and blob dir — if the
// walk ever inherited the api listing's default exclusion, the dead item's
// poster would be reference-lost and collected, and this test would fail.
func TestSettleUnionKeepsTombstonedRows(t *testing.T) {
	ctx := context.Background()
	svc, st, root := newTestService(t)
	libID, err := st.CreateLibrary(ctx, "artmod", "/media/lib", "Library")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	// Two seeded fetch rows + blob dirs: one referenced ONLY by a
	// tombstoned item's document, one referenced by nothing (the GC-ran
	// control). Both URLs target a guaranteed-refused loopback port — the
	// settle half attempts and logs the acquire, the pass continues.
	tombURL := "http://127.0.0.1:1/tmdb/tombstoned.jpg"
	unrefURL := "http://127.0.0.1:1/tmdb/unreferenced.jpg"
	tombSHA := strings.Repeat("cd", 32)
	unrefSHA := strings.Repeat("ee", 32)
	for _, seed := range []struct {
		url string
		sha string
	}{
		{tombURL, tombSHA},
		{unrefURL, unrefSHA},
	} {
		hash := urlHash(seed.url, KindPoster)
		if err := st.InsertArtFetch(ctx, hash, seed.sha, KindPoster); err != nil {
			t.Fatalf("seed fetch row %s: %v", seed.url, err)
		}
		dir := filepath.Join(root, seed.sha)
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatalf("seed blob dir: %v", err)
		}
		if err := os.WriteFile(filepath.Join(dir, "original.jpg"), []byte("bytes"), 0o644); err != nil {
			t.Fatalf("seed blob bytes: %v", err)
		}
	}

	// ONE item row: TOMBSTONED, its document the only reference holder.
	doc, err := json.Marshal(map[string]any{
		"sources": map[string]any{"tmdb": map[string]any{"poster": tombURL}},
	})
	if err != nil {
		t.Fatalf("marshal doc: %v", err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID: "itm_tomb", ModuleID: "artmod", LibraryID: libID, FileID: "file-tomb",
		RelativePath: "Gone (2000)/Gone (2000).mkv", MediaType: "movie",
		Document: doc, SchemaVersion: 1, Status: "deleted",
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}

	if err := svc.Settle(ctx); err != nil {
		t.Fatalf("Settle: %v", err)
	}

	// The tombstoned item's reference survives: fetch row + blob dir intact.
	tombHash := urlHash(tombURL, KindPoster)
	if _, err := st.LookupArtFetch(ctx, tombHash); err != nil {
		t.Fatalf("tombstoned item's fetch row lost (%v) — the GC union must read ALL rows", err)
	}
	if _, serr := os.Stat(filepath.Join(root, tombSHA)); serr != nil {
		t.Fatalf("tombstoned item's blob dir lost (%v) — artwork must survive while dead", serr)
	}

	// The control: GC ran — the row nothing references is reclaimed.
	unrefHash := urlHash(unrefURL, KindPoster)
	if _, err := st.LookupArtFetch(ctx, unrefHash); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("unreferenced fetch row survived (err %v) — GC must still run", err)
	}
	if _, serr := os.Stat(filepath.Join(root, unrefSHA)); !os.IsNotExist(serr) {
		t.Fatalf("unreferenced blob dir still on disk (%v), want reclaimed", serr)
	}
}
